"import os
import glob

server_path = r"P:\imc-server"
print(f"Checking if {server_path} exists...")
if os.path.exists(server_path):
    print("Yes, it exists!")
    # Let's list files
    try:
        files = os.listdir(server_path)
        print("Files in imc-server:")
        for f in files:
            print(f" - {f}")

        # Search for database files (.db, .sqlite, etc.)
        db_files = []
        for root, dirs, filenames in os.walk(server_path):
            for filename in filenames:
                if filename.endswith(".db") or filename.endswith(".sqlite") or "imc" in filename.lower():
                    db_files.append(os.path.join(root, filename))
