"package main

import (
	"context"
	"fmt"
	"log"

	"github.com/jackc/pgx/v5"
)

func main() {
	databaseURL := "postgres://neoroute:@@Mo1isc00@@@192.168.15.250:5432/imc_server?sslmode=disable"
	ctx := context.Background()

	conn, err := pgx.Connect(ctx, databaseURL)
	if err != nil {
		log.Fatalf("Unable to connect to database: %v\n", err)
	}
	defer conn.Close(ctx)

	fmt.Println("Connected to database successfully.")

	// Get initial count for MPB Essenciais
	var styleID string
	var initialCount int
	err = conn.QueryRow(ctx, "SELECT id FROM music_styles WHERE name = 'MPB Essenciais'").Scan(&styleID)
	if err != nil {
		log.Fatalf("Failed to find style ID: %v\n", err)
	}

	err = conn.QueryRow(ctx, "SELECT COUNT(*) FROM music_library WHERE music_style_id = $1", styleID).Scan(&initialCount)
	if err == nil {
		fmt.Printf("Initial count for MPB Essenciais: %d\n", initialCount)
	}

	// Run cleanup query
	cleanupQuery := `
		DELETE FROM music_library a
		USING music_library b
		WHERE a.music_style_id = b.music_style_id
		  AND a.file_name = b.file_name
		  AND (
			  a.created_at > b.created_at 
			  OR (a.created_at = b.created_at AND a.id > b.id)
		  )
	`

	tag, err := conn.Exec(ctx, cleanupQuery)
	if err != nil {
		log.Fatalf("Failed to execute cleanup query: %v\n", err)
	}

	rowsAffected := tag.RowsAffected()
	fmt.Printf("Cleanup complete. Rows deleted: %d\n", rowsAffected)

	// Get final count
	var finalCount int
	err = conn.QueryRow(ctx, "SELECT COUNT(*) FROM music_library WHERE music_style_id = $1", styleID).Scan(&finalCount)
	if err == nil {
		fmt.Printf("Final count for MPB Essenciais: %d\n", finalCount)
	}
}
"

